package toolchain

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/ksaze/vim-complete/internal/discover"
	"github.com/ksaze/vim-complete/internal/paths"
)

// Provides the linker.vcx script with its required module list file with stdlib
// modules and local modules from vc-build/ generated by compiler.
// Args are passed to nvim in order: mainFile, exeOut, moduleList.
func Link(root Root, mainFile, exeOut string) error {
	mainFile, err := filepath.Abs(mainFile)
	if err != nil {
		return err
	}
	exeOut, err = filepath.Abs(exeOut)
	if err != nil {
		return err
	}

	localObjs, err := discover.Files(paths.BuildDir, paths.ObjExt)
	if err != nil {
		return fmt.Errorf("discover local objects: %w", err)
	}
	stdlibObjs, err := discover.Files(root.StdlibDir, paths.ObjExt)
	if err != nil {
		return fmt.Errorf("discover stdlib objects: %w", err)
	}

	listDir, err := os.MkdirTemp("", "vc-link-*")
	if err != nil {
		return fmt.Errorf("link: create module list dir: %w", err)
	}
	defer os.RemoveAll(listDir)

	moduleList := filepath.Join(listDir, "modules.list")
	if err := writeModuleList(moduleList, localObjs, stdlibObjs); err != nil {
		return err
	}

	return Run(root, root.LinkerScript(), mainFile, exeOut, moduleList)
}

func writeModuleList(path string, localObjs, stdlibObjs []string) (retErr error) {
	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create module list: %w", err)
	}

	defer func() {
		if err := f.Close(); err != nil {
			retErr = errors.Join(retErr, fmt.Errorf("close module list: %w", err))
		}
	}()

	for _, p := range localObjs {
		if _, err := fmt.Fprintf(f, "local: %s\n", p); err != nil {
			return fmt.Errorf("write module list: %w", err)
		}
	}

	for _, p := range stdlibObjs {
		if _, err := fmt.Fprintf(f, "std: %s\n", p); err != nil {
			return fmt.Errorf("write module list: %w", err)
		}
	}

	return nil
}
